(function(root){
'use strict';
const clone=x=>JSON.parse(JSON.stringify(x));
const normalize=x=>String(x??'').trim().toLowerCase().replace(/[abcehkmoptxy]/g,c=>({'a':'а','b':'в','c':'с','e':'е','h':'н','k':'к','m':'м','o':'о','p':'р','t':'т','x':'х','y':'у'}[c]));
const matcherCache=new WeakMap();
function matcher(trait){let cached=matcherCache.get(trait);if(cached)return cached;const aliases=new Map();for(const value of trait.values)for(const alias of value.aliases){const key=normalize(alias);if(key&&!aliases.has(key))aliases.set(key,value.name);}cached={keys:trait.keys.map(normalize),aliases};matcherCache.set(trait,cached);return cached;}
const recognize=(value,trait)=>{const n=normalize(value);if(!n)return null;return matcher(trait).aliases.get(n)??null;};
function readTrait(props,trait){const prepared=new Map();for(const [name,value] of props){const key=normalize(name);if(!prepared.has(key))prepared.set(key,[]);prepared.get(key).push(value);}const preparedMatcher=matcher(trait);for(const key of preparedMatcher.keys)for(const value of prepared.get(key)||[]){const found=preparedMatcher.aliases.get(normalize(value));if(found!==undefined)return found;}return null;}
const codeOf=x=>[x.kfo,x.corpus,x.floor].filter(Boolean).join(' | ');
const status=o=>o.ff?'Завершено':o.fs?'В работе':'Не начато';
function operationStatusAt(o,t,d){if(o.ff&&t>=o.ff)return'Завершено';if(t<=d&&(!o.fs||t<o.fs))return'Не начато';if(t<=d&&o.fs&&o.fs<=t)return'В работе';if(t>d&&o.pf<=d&&!o.fs)return'Не начато';if(t>d&&o.pf<=d&&o.fs)return'В работе';if(t>d&&o.pf>d&&t>=o.pf)return'Завершено';if(t>d&&o.pf>d&&t<o.pf&&o.fs)return'В работе';if(t>d&&o.pf>d&&!o.fs&&t<o.ps)return'Не начато';if(t>d&&o.pf>d&&!o.fs&&o.ps<=t&&t<o.pf)return'В работе';return'Нет данных';}
function aggregateStatusAt(ops,t,d){const statuses=ops.map(o=>operationStatusAt(o,t,d));if(statuses.length&&statuses.every(s=>s==='Завершено'))return'Завершено';if(statuses.length&&statuses.every(s=>s==='Не начато'))return'Не начато';if(statuses.some(s=>s==='Нет данных'))return'Нет данных';return statuses.length?'В работе':'Нет данных';}
function timelineBounds(ops){const dates=ops.flatMap(o=>[o.ps,o.pf,o.fs,o.ff]).filter(Boolean).sort();return dates.length?{min:dates[0],max:dates.at(-1)}:{min:null,max:null};}
function groupOperations(ops){const map=new Map();for(const o of ops){const code=codeOf(o);if(!map.has(code))map.set(code,{code,ops:[]});map.get(code).ops.push(o);}return [...map.values()].map(g=>{const s=g.ops.map(status);return {...g,ps:min(g.ops.map(o=>o.ps)),pf:max(g.ops.map(o=>o.pf)),fs:min(g.ops.map(o=>o.fs)),ff:g.ops.every(o=>o.ff)?max(g.ops.map(o=>o.ff)):null,status:s.every(x=>x==='Завершено')?'Завершено':s.every(x=>x==='Не начато')?'Не начато':'В работе'};});}
function min(a){return a.filter(Boolean).sort()[0]||null;}function max(a){return a.filter(Boolean).sort().at(-1)||null;}
function groupModels(models,traits){const groups=new Map(),summary=[];for(const m of models.filter(m=>m.selected!==null)){let read=0;if(!m.elements.length){if(!groups.has('Без КФО'))groups.set('Без КФО',{code:'Без КФО',models:[],count:0,status:'Нет данных',stage:null});groups.get('Без КФО').models.push({id:m.id,name:m.name,count:0});}for(const e of m.elements){const obj={};for(const t of traits)obj[t.id]=t.derivedFrom?recognize(obj[t.derivedFrom],t):readTrait(e.props,t);const code=obj.kfo?codeOf(obj):'Без КФО';if(obj.kfo)read++;if(!groups.has(code))groups.set(code,{code,models:[],count:0,status:'Нет данных',stage:obj.constructionStage||null});const g=groups.get(code);let child=g.models.find(x=>x.id===m.id);if(!child){child={id:m.id,name:m.name,count:0};g.models.push(child);}g.count++;child.count++;}summary.push({name:m.name,total:m.elements.length,read,unread:m.elements.length-read});}return {groups:[...groups.values()],summary};}
function stageOfKfo(kfo,traits){const trait=(traits||[]).find(item=>item.id==='constructionStage');return trait?recognize(kfo,trait):null;}
function filterOperationsByStage(operations,stage,traits){return stage==='all'?[...(operations||[])]:((operations||[]).filter(operation=>stageOfKfo(operation.kfo,traits)===stage));}
function filterModelGroupsByStage(groups,stage){return stage==='all'?[...(groups||[])]:((groups||[]).filter(group=>group.stage===stage));}
function linkScheduleModels(ops,modelGroups){const schedule=groupOperations(ops),scheduleByCode=new Map(schedule.map(group=>[normalize(group.code),group])),modelsByCode=new Map(modelGroups.map(group=>[normalize(group.code),group]));return {schedule:schedule.map(group=>{const model=modelsByCode.get(normalize(group.code));return {...group,count:model?.count||0,models:model?.models||[]};}),models:modelGroups.map(group=>{const work=scheduleByCode.get(normalize(group.code));return {...group,ops:work?.ops||[],ps:work?.ps||null,pf:work?.pf||null,fs:work?.fs||null,ff:work?.ff||null,status:work?.status||'Нет данных'};})};}
function validateTraits(traits){const errors=[],keys=new Map();for(const t of traits){if(!t.keys.length)errors.push(`${t.name}: добавьте хотя бы один ключ признака.`);if(!t.values.length)errors.push(`${t.name}: добавьте хотя бы одно мастер-значение.`);for(const k of t.keys){const n=normalize(k);if(!n)errors.push(`${t.name}: заполните ключ признака.`);else if(!t.derivedFrom&&keys.has(n))errors.push(`Ключ «${k}» уже используется в признаке «${keys.get(n)}».`);else if(!t.derivedFrom)keys.set(n,t.name);}const names=new Set(),aliases=new Map();for(const v of t.values){const name=normalize(v.name);if(!name)errors.push('Заполните название мастер-значения.');else if(names.has(name))errors.push(`Название «${v.name}» уже используется в признаке «${t.name}».`);names.add(name);if(!v.aliases.length)errors.push(`${v.name||'Новое МЗ'}: добавьте хотя бы один допустимый вариант.`);for(const a of v.aliases){const n=normalize(a);if(!n)errors.push(`${v.name}: заполните допустимый вариант.`);else if(aliases.has(n))errors.push(`Вариант «${a}» уже используется у мастер-значения «${aliases.get(n)}».`);else aliases.set(n,v.name);}}}return [...new Set(errors)];}
function mergeUnique(current,baseline){const result=[],seen=new Set();for(const value of [...current,...baseline]){const key=normalize(value);if(key&&!seen.has(key)){seen.add(key);result.push(value);}}return result;}
function mergeTraitCatalog(saved,baseline){const savedById=new Map((saved||[]).map(trait=>[trait.id,trait]));return (baseline||[]).map(base=>{const current=savedById.get(base.id);if(!current)return clone(base);const values=clone(current.values||[]),byName=new Map(values.map(value=>[normalize(value.name),value]));for(const baseValue of base.values||[]){const existing=byName.get(normalize(baseValue.name));if(existing)existing.aliases=base.replaceAliases?clone(baseValue.aliases||[]):mergeUnique(existing.aliases||[],baseValue.aliases||[]);else{const added=clone(baseValue);values.push(added);byName.set(normalize(added.name),added);}}return {id:base.id,name:base.name,keys:mergeUnique(current.keys||[],base.keys||[]),values,derivedFrom:base.derivedFrom||current.derivedFrom||null,replaceAliases:base.replaceAliases||current.replaceAliases||false};});}
function validateImport(rows,d,traits){const errors=[],accepted=[];let fatal=false,maxFact=null;const displayDate=x=>x&&/^\d{4}-\d{2}-\d{2}$/.test(x)?x.split('-').reverse().join('.'):x;
function err(row,field,col,value,reason,critical=false){errors.push({type:critical?'Критическая ошибка загрузки графика':'Критическая ошибка загрузки операции',row,field,col,value:value??'',reason});if(critical)fatal=true;}
for(const r of rows){const before=errors.length;const out={name:String(r.name||'').trim(),stage:String(r.stage||'').trim(),row:r.row};for(const [id,col] of [['kfo','K'],['corpus','AI'],['floor','AJ']]){const t=traits.find(t=>t.id===id),value=r[id];out[id]=recognize(value,t);if(!normalize(value)){if(id==='kfo')err(r.row,t.name,col,value,'Не указан Код КФО.',true);}else if(!out[id])err(r.row,t.name,col,value,`Не найдено соответствие для ${t.name} «${value}».`,true);}if(!out.stage){const stageTrait=traits.find(t=>t.id==='constructionStage');out.stage=stageTrait?recognize(out.kfo,stageTrait)||'':'';}
if(!out.name)err(r.row,'Наименование операции','B',r.name,'Не указано наименование операции.');
for(const [id,col,label,required] of [['ps','R','Плановое начало',true],['pf','S','Плановое окончание',true],['fs','T','Фактическое начало',false],['ff','U','Фактическое окончание',false]]){out[id]=r[id]||null;if(!r[id]&&required)err(r.row,label,col,r[id],id==='ps'?'Не указано плановое начало.':'Не указано плановое окончание.');else if(r[id]==='INVALID')err(r.row,label,col,r.rawDates?.[id]||r[id],`Некорректный тип или значение даты в поле «${label}».`);else if((id==='fs'||id==='ff')&&r[id]){if(!maxFact||r[id]>maxFact)maxFact=r[id];if(r[id]>d)err(r.row,label,col,r[id],`${label} позже отчётной даты.`);}}
if(out.ps&&out.pf&&out.ps!=='INVALID'&&out.pf!=='INVALID'&&out.pf<out.ps)err(r.row,'Плановое окончание','S',out.pf,'Плановое окончание раньше планового начала.');
if(out.ff&&!out.fs)err(r.row,'Фактическое окончание','U',out.ff,'Указано фактическое окончание без фактического начала.');
if(out.fs&&out.ff&&out.fs!=='INVALID'&&out.ff!=='INVALID'&&out.ff<out.fs)err(r.row,'Фактическое окончание','U',out.ff,'Фактическое окончание раньше фактического начала.');
if(errors.length===before)accepted.push(out);}
if(!rows.length)err(null,'Операции','',null,'Нет операций для загрузки.',true);
if(maxFact&&maxFact>d)err(null,'Отчётная дата','B1',d,`Максимальная фактическая дата «${displayDate(maxFact)}» позже отчётной даты «${displayDate(d)}». Укажите отчётную дату не раньше «${displayDate(maxFact)}».`,true);
const ops=fatal?[]:accepted;return {ops,errors,total:rows.length,loaded:ops.length,rejected:rows.length-ops.length,result:!ops.length?'error':ops.length<rows.length?'partial':'success'};}
function demoRows(){const stages=['Фундамент','Shell&Core','Фасады','Кровля','FitOut'];return Array.from({length:24},(_,i)=>({row:i+4,kfo:['204.02.01.01','204.02.01.02','204.02.02.01','204.02.03.01'][i%4],corpus:'Корпус А',floor:i%2?'02':'1',stage:stages[i%stages.length],name:['Устройство монолитных стен','Армирование перекрытия','Монтаж опалубки','Бетонирование перекрытия'][i%4],ps:`2026-09-${String(1+i).padStart(2,'0')}`,pf:`2026-10-${String(1+i).padStart(2,'0')}`,fs:i<18?`2026-09-${String(2+i).padStart(2,'0')}`:null,ff:i<8?`2026-10-${String(2+i).padStart(2,'0')}`:null}));}
const api={clone,normalize,recognize,readTrait,codeOf,status,operationStatusAt,aggregateStatusAt,timelineBounds,groupOperations,groupModels,stageOfKfo,filterOperationsByStage,filterModelGroupsByStage,linkScheduleModels,validateTraits,mergeTraitCatalog,validateImport,demoRows,min,max};if(typeof module!=='undefined')module.exports=api;root.Core=api;
})(typeof window!=='undefined'?window:globalThis);
